input.command:
set -e
# live config
ip addr add 203.0.113.2/30 dev eth2
ip route add default via 203.0.113.1 dev eth2
# persistent interface config (only eth2 matched)
cat > /etc/systemd/network/10-wan-eth2.network <<'EOF'
[Match]
Name=eth2

[Network]
Address=203.0.113.2/30
Gateway=203.0.113.1
EOF
echo 'net.ipv4.ip_forward = 1' > /etc/sysctl.d/90-forward.conf
# nftables: own tables, don't flush other (docker/iptables-nft) tables
cat > /etc/nftables.conf <<'EOF'
#!/usr/sbin/nft -f
# Egress for LAN 192.168.10.0/24 via eth2 (203.0.113.2)

table inet filter
delete table inet filter

table inet filter {
	chain input {
		type filter hook input priority filter;
	}
	chain forward {
		type filter hook forward priority filter; policy accept;
		ct state established,related accept
		ct state invalid drop
		iifname "eth1" oifname "eth2" ip saddr 192.168.10.0/24 accept
	}
	chain output {
		type filter hook output priority filter;
	}
}

table ip egress_nat
delete table ip egress_nat

table ip egress_nat {
	chain postrouting {
		type nat hook postrouting priority srcnat; policy accept;
		ip saddr 192.168.10.0/24 oifname "eth2" snat to 203.0.113.2
	}
}
EOF
nft -c -f /etc/nftables.conf && nft -f /etc/nftables.conf
systemctl enable nftables systemd-networkd 2>&1 | tail -2
sysctl -p /etc/sysctl.d/90-forward.conf
ip route; nft list ruleset | grep -A8 -E "egress_nat|forward"

